INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES ('v138', '侧边栏竖线可以向左拖动收窄', '修好了侧边栏（智能体竖栏）右边缘那条竖线只能往右拖、往左拖不动的问题：以前拖动是从保存的宽度数字算起的，手机上侧边栏实际显示的宽度有一道上限，保存的数字一旦超过这个上限，往左拖时手指在动、数字在降，画面却要等数字降到上限以下才开始变窄，看起来就像只能往右拖。现在拖动改为从屏幕上实际显示的宽度算起，往左拖第一下就开始收窄，往右拖也一样跟手；同时手机上拖动时也关掉了宽度过渡动画，边缘逐帧贴着手指走，不再拖尾。桌面端和列表栏竖线、菜单横线的拖动方式不变，松手仍自动保存。', strftime('%s','now') * 1000);
